from flask import Flask, jsonify, render_template

app = Flask(__name__)

@app.get('/')
def inicio():
    return render_template('index.html')

@app.get('/api/estado')
def estado():
    return jsonify({'estado': 'Esperando una acción...'})

if __name__ == '__main__':
    app.run(debug=False)

