import sqlite3

DB = sqlite3.connect(':memory:')
DB.execute('CREATE TABLE objetos (id INTEGER PRIMARY KEY, nombre TEXT NOT NULL, cantidad INTEGER NOT NULL)')


def mostrar_inventario():
    filas = DB.execute('SELECT id, nombre, cantidad FROM objetos ORDER BY id').fetchall()
    for fila in filas:
        print(fila)


if __name__ == '__main__':
    mostrar_inventario()
